param([string]$EnvFile = ".env")
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop";$repoRoot=Split-Path -Parent $PSScriptRoot;$envPath=if([IO.Path]::IsPathRooted($EnvFile)){$EnvFile}else{Join-Path $repoRoot $EnvFile};$remoteRoot="/home/testpilot/mim"
function Get-EnvValue {param([string]$Name)$line=Get-Content -LiteralPath $envPath|Where-Object{$_ -match ("^\s*{0}\s*=" -f [regex]::Escape($Name))}|Select-Object -First 1;if(-not $line){return ""};return(($line -replace ("^\s*{0}\s*=\s*" -f [regex]::Escape($Name)),"").Trim().Trim('"'))}
function Invoke-RemoteChecked {param([int]$SessionId,[string]$Command,[int]$TimeoutSeconds=120)$r=Invoke-SSHCommand -SessionId $SessionId -Command $Command -TimeOut $TimeoutSeconds;if($r.ExitStatus -ne 0){throw "Remote command failed $($r.ExitStatus): output=$($r.Output -join ' | ') error=$($r.Error -join '; ')"};return $r}
function Send-RemoteFileB64 {param([int]$SessionId,[string]$LocalPath,[string]$RemotePath)$full=(Resolve-Path(Join-Path $repoRoot $LocalPath)).Path;$encoded=[Convert]::ToBase64String([IO.File]::ReadAllBytes($full));$tmp="/tmp/codex_ent_2fa_smoke_$([Guid]::NewGuid().ToString('N')).b64";for($o=0;$o-lt$encoded.Length;$o+=12000){$c=$encoded.Substring($o,[Math]::Min(12000,$encoded.Length-$o));Invoke-RemoteChecked $SessionId "printf '%s' '$c' >> '$tmp'"|Out-Null};Invoke-RemoteChecked $SessionId "base64 -d '$tmp' > '$RemotePath' && rm -f '$tmp'"|Out-Null}
Import-Module Posh-SSH -ErrorAction Stop;$credential=[pscredential]::new((Get-EnvValue "MIM_SSH_USER"),(ConvertTo-SecureString (Get-EnvValue "MIM_SSH_PASSWORD") -AsPlainText -Force));$pt=Get-EnvValue "MIM_SSH_PORT";$port=if($pt){[int]$pt}else{22};$session=New-SSHSession -ComputerName (Get-EnvValue "MIM_SSH_HOST") -Port $port -Credential $credential -AcceptKey -Force
try{Send-RemoteFileB64 $session.SessionId "runtime_remote_training/remote_scripts/smoke_ent_two_factor_live_v1.py" "$remoteRoot/scripts/smoke_ent_two_factor_live_v1.py";(Invoke-RemoteChecked $session.SessionId "cd '$remoteRoot' && PYTHONPATH='$remoteRoot' .venv/bin/python scripts/smoke_ent_two_factor_live_v1.py" 180).Output}finally{if($session){Remove-SSHSession -SessionId $session.SessionId|Out-Null}}
